// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        // The contract is deployed with owner == address(0); that owner hands
        // ownership to the fuzzed caller first (no assumption rejection needed).
        vm.prank(address(0));
        c.transferOwnership(caller);
        // General rule: the current owner can always pass ownership on to any
        // address, and afterwards the getter reports that new owner.
        vm.prank(caller);
        c.transferOwnership(newOwner);
        assertTrue(c.owner() == newOwner);
    }
}
